type official =
  | Secretary
  | Other_official of string  (* placeholder identity of the other US official referenced *)

(* delegate as defined by 7701(a)(12)(A): officer, employee, or agency
   duly authorized (directly or via one or more redelegations) to perform
   the function mentioned or described in context *)
type delegate = {
  delegate_entity : string;          (* officer, employee, or agency *)
  authorizing_official : official;   (* official whose authority is delegated *)
  duly_authorized : bool;            (* authorized directly or indirectly by redelegation *)
}

let is_secretary (ref_official : official) : bool =
  match ref_official with
  | Secretary -> true
  | Other_official _ -> false

(* (i): reference to Secretary of the Treasury *)
let meaning_of_delegate_secretary (ref_official : official) : delegate =
  { delegate_entity = "officer_employee_or_agency_of_treasury";
    authorizing_official = ref_official;
    duly_authorized = true }

(* (ii): reference to any other official of the United States, similarly construed *)
let meaning_of_delegate_other (ref_official : official) : delegate =
  { delegate_entity = "officer_employee_or_agency_of_official";
    authorizing_official = ref_official;
    duly_authorized = true }

(* (A): dispatch on whether reference is to Secretary or other official *)
let meaning_of_delegate (ref_official : official) : delegate =
  if is_secretary ref_official then meaning_of_delegate_secretary ref_official
  else meaning_of_delegate_other ref_official
